        // Overload for Button.Click (RoutedEventArgs) — dashboard admin banner
        internal void AdminModeBadge_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                bool isAdm = SMDWin.Services.PermissionHelper.IsRunningAsAdmin();

                // Update the sidebar label
                if (FindName("TxtAdminModeLabel") is System.Windows.Controls.TextBlock aml)
                    aml.Text = isAdm ? "Admin Mode" : "User Mode";

                if (isAdm)
                {
                    ShowToastSuccess(_LS("Common", "AlreadyAdmin"));
                    return;
                }

                // Not running as admin — offer an elevated restart.
                var ans = System.Windows.MessageBox.Show(
                    _LS("Common", "RestartAsAdminConfirm"),
                    "SMD Win", System.Windows.MessageBoxButton.YesNo, System.Windows.MessageBoxImage.Question);
                if (ans != System.Windows.MessageBoxResult.Yes) return;

                var exe = System.Diagnostics.Process.GetCurrentProcess().MainModule?.FileName;
                if (string.IsNullOrEmpty(exe)) return;
                var psi = new System.Diagnostics.ProcessStartInfo
                {
                    FileName = exe,
                    Arguments = "--restart",
                    UseShellExecute = true,
                    Verb = "runas"   // triggers UAC
                };
                try
                {
                    System.Diagnostics.Process.Start(psi);
                    _isClosingToTray = true;     // iesim complet, nu in tray
                    System.Windows.Application.Current.Shutdown();
                }
                catch (System.ComponentModel.Win32Exception)
                {
                    // the user cancelled the UAC prompt — do nothing
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.AdminModeBadge_Click"); }
        }

        private void RetrySensors_Click(object sender, System.Windows.RoutedEventArgs e)
        {
            // Re-initialize TempReader on background thread
            _ = Task.Run(() =>  // CS4014: fire-and-forget intentional — UI feedback via Dispatcher below
            {
                try
                {
                    _tempReader?.Dispose();
                    _tempReader = new SMDWin.Services.TempReader();
                    _ = Dispatcher.InvokeAsync(() => { });
                }
                catch (Exception ex)
                {
                    AppLogger.Warning(ex, "MainWindow.RetrySensors_Click");
                    _ = Dispatcher.InvokeAsync(() => { });
                }
            });
        }

