        // PIN PROCESS AS WIDGET — from Process Monitor context menu
        // ══════════════════════════════════════════════════════════════════════
        private void PinProcessAsWidget_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                dynamic? selected = ProcessesGrid?.SelectedItem;
                if (selected == null) return;

                int pid = (int)selected.Pid;
                string name = (string)selected.Name;

                // Check if already pinned
                var existing = System.Windows.Application.Current.Windows
                    .OfType<SMDWin.Views.PinnedProcessWindow>()
                    .FirstOrDefault(w =>
                    {
                        try { return w.Title.Contains(name); } catch { return false; }
                    });
                if (existing != null)
                {
                    existing.Activate();
                    return;
                }

                var pinned = new SMDWin.Views.PinnedProcessWindow(pid, name);
                // Don't set Owner — prevents hide-on-minimize; WidgetManager handles stacking
                SMDWin.Services.WidgetManager.Register(pinned);
                pinned.Show();
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.PinProcessAsWidget_Click"); }
        }

        private static readonly string _regPath = @"Software\SMDWin\Sensors";
        private void ExportToRegistry(SMDWin.Services.TempSnapshot? snap, float cpuPct, float ramPct)
        {
            if (snap == null) return;
            try
            {
                using var key = Microsoft.Win32.Registry.CurrentUser.CreateSubKey(_regPath);
                if (key == null) return;
                key.SetValue("CpuTempC",    snap.CpuTemp?.ToString("F1") ?? "");
                key.SetValue("GpuTempC",    snap.GpuTemp?.ToString("F1") ?? "");
                key.SetValue("CpuLoadPct",  cpuPct.ToString("F0"));
                key.SetValue("RamPct",      ramPct.ToString("F0"));
                key.SetValue("CpuFreqMHz",  snap.CpuFreqMHz?.ToString("F0") ?? "");
                key.SetValue("GpuFreqMHz",  snap.GpuFreqMHz?.ToString("F0") ?? "");
                key.SetValue("CpuPowerW",   snap.CpuPowerW?.ToString("F1") ?? "");
                key.SetValue("GpuPowerW",   snap.GpuPowerW?.ToString("F1") ?? "");
                key.SetValue("VCoreV",      snap.CpuVCoreV?.ToString("F3") ?? "");
                key.SetValue("NetDownKBs",  _emaNetDown.ToString("F0"));
                key.SetValue("NetUpKBs",    _emaNetUp.ToString("F0"));
                key.SetValue("Timestamp",   DateTime.Now.ToString("HH:mm:ss"));
            }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* registry write optional */ }
        }

