        private void BtnAbout_Click(object s, RoutedEventArgs e)
        {
            try
            {
                var win = new AboutWindow { Owner = this, ShowInTaskbar = true };
                Ui.FixOwnedWindowMinimize(win, this);
                SMDWin.Services.ThemeManager.Apply(
                    SMDWin.Services.SettingsService.Current.ThemeName == "Auto"
                        ? SMDWin.Services.ThemeManager.ResolveAuto()
                        : SMDWin.Services.SettingsService.Current.ThemeName,
                    win.Resources);
                win.Show();
            }
            catch (Exception ex) { AppLogger.Warning(ex, "BtnAbout_Click"); }
        }
